// DNS correlation v1: state is intentionally small and workflow-local.
// This endpoint receives only compact *current* observations. Probe authority stays
// with the monitors; this workflow derives cross-vantage condition transitions.
const body = $json.body ?? $json;
const nowMs = Date.now();
const now = new Date(nowMs).toISOString();
const INTERNAL = 'internal-dns-monitor';
const EXTERNAL = 'external-dns-resilience';
const ACCEPTED = new Set([INTERNAL, EXTERNAL]);
const CONDITION_NAMES = [
  'dns_service_impact',
  'individual_resolver_degradation',
  'lan_resolver_selection_failure',
  'external_path_impairment',
  'midway_recursion_instability',
  'internal_observer_stale',
];
// Midway-only evidence is intentionally never delivered to Operational Event Ingress.
const ACTIONABLE = new Set(CONDITION_NAMES.filter(name => name !== 'midway_recursion_instability'));
const FRESH_MS = 6 * 60 * 1000;
const BOOTSTRAP_GRACE_MS = 6 * 60 * 1000;
const RETENTION_MS = 48 * 60 * 60 * 1000;
const MAX_OBSERVERS = 8;
const MAX_DELIVERIES = 32;

function reject(message, details = {}) {
  return [{ json: {
    responseCode: 400,
    response: { accepted: false, error: 'invalid_dns_observation', message, details },
    deliveryQueue: [],
  }}];
}
function bool(value) { return typeof value === 'boolean'; }
function validExecution(value) {
  return value && typeof value === 'object' &&
    typeof value.host === 'string' && value.host.length > 0 &&
    typeof value.vantage === 'string' && value.vantage.length > 0;
}
function observerSummary(source, checks) {
  if (source === INTERNAL) return {
    client_path: checks.client_path,
    resolvers: { pihole_a: checks.resolvers.pihole_a, pihole_b: checks.resolvers.pihole_b },
  };
  return {
    external_path: checks.external_path,
    resolvers: { pihole_a: checks.resolvers.pihole_a, pihole_b: checks.resolvers.pihole_b },
    midway_recursion: checks.midway_recursion,
  };
}

if (!body || typeof body !== 'object' || Array.isArray(body)) return reject('Body must be one observation object');
const required = ['contract_version', 'source', 'observed_at', 'sequence', 'execution', 'checks'];
const missing = required.filter(key => body[key] === undefined || body[key] === null || body[key] === '');
if (missing.length) return reject('Missing required fields', { missing });
if (body.contract_version !== '1.0') return reject('Unsupported contract_version', { expected: '1.0' });
if (!ACCEPTED.has(body.source)) return reject('Unsupported source', { accepted_sources: [...ACCEPTED] });
if (!Number.isSafeInteger(body.sequence) || body.sequence < 0) return reject('sequence must be a non-negative integer');
if (!validExecution(body.execution)) return reject('execution.host and execution.vantage are required strings');
const observedMs = Date.parse(body.observed_at);
if (!Number.isFinite(observedMs) || observedMs > nowMs + 5 * 60 * 1000) return reject('observed_at must be ISO-8601 and not more than five minutes in the future');
const checks = body.checks;
if (!checks || typeof checks !== 'object' || !checks.resolvers || typeof checks.resolvers !== 'object') return reject('checks.resolvers is required');
if (!bool(checks.resolvers.pihole_a) || !bool(checks.resolvers.pihole_b)) return reject('checks.resolvers.pihole_a and checks.resolvers.pihole_b must be booleans');
if (body.source === INTERNAL) {
  // Critical policy boundary: ordinary IX/LAN clients must not query Midway directly.
  if (Object.hasOwn(checks, 'midway_recursion')) return reject('Internal observations must not include direct Midway evidence');
  if (!bool(checks.client_path)) return reject('Internal observations require checks.client_path boolean');
}
if (body.source === EXTERNAL) {
  if (!bool(checks.external_path) || !bool(checks.midway_recursion)) return reject('External observations require checks.external_path and checks.midway_recursion booleans');
}

const store = $getWorkflowStaticData('global');
if (store.schema !== 1) {
  // Only bounded state: latest observer summaries, six condition episodes, and a
  // short delivery audit. This intentionally replaces unavailable Data Tables.
  Object.assign(store, {
    schema: 1,
    bootstrapped_at: now,
    observers: {},
    conditions: {},
    pending_events: {},
    delivered_event_ids: {},
    delivery_audit: [],
  });
}
store.observers ??= {};
store.conditions ??= {};
store.pending_events ??= {};
store.delivered_event_ids ??= {};
store.delivery_audit ??= [];
const previous = store.observers[body.source];
if (previous && body.sequence <= previous.sequence) {
  return [{ json: {
    responseCode: 202,
    response: { accepted: true, duplicate_or_out_of_order: true, source: body.source, sequence: body.sequence },
    deliveryQueue: [],
  }}];
}

store.observers[body.source] = {
  sequence: body.sequence,
  received_at: now,
  observed_at: body.observed_at,
  execution: { host: body.execution.host, vantage: body.execution.vantage, runtime_revision: body.execution.runtime_revision ?? null },
  checks: observerSummary(body.source, checks),
};
// Prune old/unknown observers and hard-bound retention even if new sources are added later.
for (const [source, observer] of Object.entries(store.observers)) {
  if (!Number.isFinite(Date.parse(observer.received_at)) || nowMs - Date.parse(observer.received_at) > RETENTION_MS) delete store.observers[source];
}
const orderedSources = Object.entries(store.observers).sort((a, b) => Date.parse(b[1].received_at) - Date.parse(a[1].received_at));
for (const [source] of orderedSources.slice(MAX_OBSERVERS)) delete store.observers[source];

const internal = store.observers[INTERNAL];
const external = store.observers[EXTERNAL];
const internalFresh = Boolean(internal) && nowMs - Date.parse(internal.received_at) <= FRESH_MS;
const desired = Object.fromEntries(CONDITION_NAMES.map(name => [name, false]));

if (internalFresh) {
  const i = internal.checks;
  if (!i.client_path) {
    // A failed client path with both direct Pi-hole checks healthy is resolver
    // selection/path trouble, not evidence that the DNS service itself is down.
    if (i.resolvers.pihole_a && i.resolvers.pihole_b) desired.lan_resolver_selection_failure = true;
    else desired.dns_service_impact = true;
  } else if (i.resolvers.pihole_a !== i.resolvers.pihole_b) {
    desired.individual_resolver_degradation = true;
  }
} else if (nowMs - Date.parse(store.bootstrapped_at) >= BOOTSTRAP_GRACE_MS) {
  // Loss of LAN-side corroboration is observable only when a webhook call arrives.
  desired.internal_observer_stale = true;
}

if (external) {
  const e = external.checks;
  if (!e.external_path && internalFresh && internal.checks.client_path) {
    desired.external_path_impairment = true;
  }
  // The only permitted direct Midway evidence is from the external observer.
  // It is diagnostic only and does not become an operational-ingress event.
  if (!e.midway_recursion && internalFresh && internal.checks.client_path &&
      internal.checks.resolvers.pihole_a && internal.checks.resolvers.pihole_b) {
    desired.midway_recursion_instability = true;
  }
}

function eventFor(condition, transition, episode, evidence) {
  const open = transition === 'opened';
  return {
    contract_version: '1.0',
    event_id: `dns-correlation-state:${condition}:${transition}:${episode}`,
    incident_key: `dns-correlation-state:${condition}`,
    source: 'dns-correlation-state',
    owner: 'network',
    category: 'dns',
    severity: condition === 'dns_service_impact' ? 'critical' : 'warning',
    state: open ? 'degraded' : 'healthy',
    transition,
    title: `${condition.replaceAll('_', ' ')} ${transition}`,
    message: open
      ? `DNS correlation opened ${condition} from compact current observations.`
      : `DNS correlation recovered ${condition} from compact current observations.`,
    occurred_at: now,
    execution: { host: 'n8n', vantage: 'dns-correlation-state', runtime_revision: 'workflow-staticdata-v1' },
    details: { condition, episode, evidence },
  };
}
function queuePending(event) {
  if (store.delivered_event_ids[event.event_id]) return;
  store.pending_events[event.event_id] ??= { event, queued_at: now };
}

const transitions = [];
let deliveryQueue = [];
const diagnosticTransitions = [];
const evidence = {
  received_source: body.source,
  received_sequence: body.sequence,
  internal_fresh: internalFresh,
  observers: Object.fromEntries(Object.entries(store.observers).map(([source, o]) => [source, {
    observed_at: o.observed_at, execution: o.execution, checks: o.checks,
  }])),
};
for (const condition of CONDITION_NAMES) {
  const episode = store.conditions[condition] ?? { open: false, episode: 0 };
  const open = Boolean(episode.open);
  if (open === desired[condition]) continue;
  const transition = desired[condition] ? 'opened' : 'recovered';
  if (desired[condition]) episode.episode += 1;
  episode.open = desired[condition];
  episode.changed_at = now;
  episode.last_evidence = evidence;
  store.conditions[condition] = episode;
  const transitionRecord = { condition, transition, episode: episode.episode, occurred_at: now };
  transitions.push(transitionRecord);
  if (!ACTIONABLE.has(condition)) {
    diagnosticTransitions.push(transitionRecord);
    continue;
  }
  queuePending(eventFor(condition, transition, episode.episode, evidence));
}
// Backfill any current open episode lacking a recorded ingress acceptance. This
// recovers pre-outbox state safely: ingress deduplicates the stable event ID.
for (const condition of CONDITION_NAMES) {
  const episode = store.conditions[condition];
  if (ACTIONABLE.has(condition) && episode?.open && episode.episode > 0) {
    queuePending(eventFor(condition, 'opened', episode.episode, episode.last_evidence ?? evidence));
  }
}
deliveryQueue = Object.values(store.pending_events)
  .sort((a, b) => String(a.queued_at).localeCompare(String(b.queued_at)))
  .map(entry => entry.event);

return [{ json: {
  responseCode: 202,
  response: {
    accepted: true,
    source: body.source,
    sequence: body.sequence,
    derived_conditions: Object.entries(desired).filter(([, open]) => open).map(([name]) => name),
    transitions,
    promoted_count: deliveryQueue.length,
    unalerted_diagnostic_transitions: diagnosticTransitions,
  },
  deliveryQueue,
}}];

// The response was already sent (202/400). Emit only actionable transition events.
const result = $('Correlate Current Observation').first().json;
if (result.responseCode !== 202 || !Array.isArray(result.deliveryQueue)) return [];
return result.deliveryQueue.map(event => ({ json: { event } }));

// Acknowledgement is durable workflow state, separate from condition truth.
const store = $getWorkflowStaticData('global');
store.pending_events ??= {};
store.delivered_event_ids ??= {};
store.delivery_audit ??= [];
const event = $('Expand Actionable Transition Events').item.json.event;
delete store.pending_events[event.event_id];
store.delivered_event_ids[event.event_id] = new Date().toISOString();
const delivered = Object.entries(store.delivered_event_ids).sort((a, b) => String(a[1]).localeCompare(String(b[1])));
for (const [eventId] of delivered.slice(0, Math.max(0, delivered.length - 32))) delete store.delivered_event_ids[eventId];
store.delivery_audit.push({ event_id: event.event_id, result: 'accepted_by_ingress', at: new Date().toISOString() });
if (store.delivery_audit.length > 32) store.delivery_audit.splice(0, store.delivery_audit.length - 32);
return [{ json: { recorded: true, event_id: event.event_id } }];

// Retain the exact event for a later current observation; never regenerate an ID.
const store = $getWorkflowStaticData('global');
store.pending_events ??= {};
store.delivery_audit ??= [];
const event = $('Expand Actionable Transition Events').item.json.event;
store.pending_events[event.event_id] ??= { event, queued_at: new Date().toISOString() };
store.delivery_audit.push({ event_id: event.event_id, result: 'ingress_delivery_failed', at: new Date().toISOString(), node: $json.error?.node?.name ?? 'HTTP Request' });
if (store.delivery_audit.length > 32) store.delivery_audit.splice(0, store.delivery_audit.length - 32);
return [{ json: { recorded: true, result: 'ingress_delivery_failed', event_id: event.event_id } }];
